const items = $input.all();
const results = [];
const seenItems = new Map(); // Track by title+date combo
let gnewsSeen = 0;
let gnewsUnwrapped = 0;

const identifySource = (link, title, creator) => {
  const lowerTitle = title.toLowerCase();
  const lowerLink = link.toLowerCase();

  if (lowerLink.includes('sec.gov')) return 'SEC Press Releases';
  if (lowerLink.includes('federalregister.gov')) {
    const lowerCreator = (creator || '').toLowerCase();
    if (lowerCreator.includes('commodity futures trading commission') || lowerLink.includes('commodity-futures') || lowerTitle.includes('cftc')) {
      return 'CFTC Regulations';
    }
    if (lowerCreator.includes('securities and exchange commission')) {
      return 'Federal Register - Securities';
    }
    if (lowerCreator.includes('financial industry regulatory authority')) {
      return 'FINRA Enforcement News';
    }
    // Federal Register's dc:creator reliably carries the actual issuing agency's full name
    // (verified live 2026-08-30). Anything not SEC/CFTC/FINRA is a real non-financial agency
    // (FCC, EEOC, DOT, etc.) pulled in by the loose 'securities+investment' term search
    // -- label it honestly instead of defaulting every unmatched item to 'Securities'.
    if (creator && creator !== 'Unknown') {
      return `Federal Register - ${creator}`;
    }
    return 'Unknown Source';
  }
  if (lowerLink.includes('finra.org')) return 'FINRA Enforcement News';

  if (lowerLink.includes('news.google.com')) {
    if (lowerTitle.includes('finra')) return 'FINRA Enforcement News';
    if (lowerTitle.includes('investment advisor') || lowerTitle.includes('investment adviser')) {
      return 'Investment Advisor Rules';
    }
    if (lowerTitle.includes('sec') || lowerTitle.includes('securities')) {
      return 'SEC Press Releases';
    }
    if (lowerTitle.includes('cftc') || lowerTitle.includes('commodity')) {
      return 'CFTC Regulations';
    }
    // Secondary, feed-agnostic signals (verified live 2026-08-30 to recover ~56% of
    // items that otherwise fell through to Unknown Source, with zero effect on
    // items already classified above -- these only ever fire on the leftover items).
    if (/\bria\b/.test(lowerTitle) || lowerTitle.includes('adviser') || lowerTitle.includes('advisor')) {
      return 'Investment Advisor Rules';
    }
    if (lowerTitle.includes('broker-dealer') || lowerTitle.includes('broker dealer') || /\breg\s?bi\b/.test(lowerTitle)) {
      return 'FINRA Enforcement News';
    }
  }

  if (creator) {
    const lowerCreator = creator.toLowerCase();
    if (lowerCreator.includes('finra')) return 'FINRA Enforcement News';
    if (lowerCreator.includes('sec.gov')) return 'SEC Press Releases';
    if (lowerCreator.includes('cftc')) return 'CFTC Regulations';
  }

  return 'Unknown Source';
};

// Resolve the real destination URL behind a Google News redirect. Modern Google
// News links (news.google.com/rss/articles/<opaque-id>?oc=5) carry no plain
// query-param URL and don't 302 to the article -- the real URL is only obtainable
// via the same internal batchexecute call the Google News web page itself makes.
// Live-verified 2026-08-31: 36/36 real items decoded successfully across both
// Google News feeds. Falls back to the original redirect link on ANY failure
// (network error, unexpected page format, endpoint change) so a broken decode
// never breaks the run -- it just silently loses the upgrade for that one item,
// which is why gnewsSeen/gnewsUnwrapped are logged below (never let this
// degrade invisibly).
const GNEWS_DECODE_RPC = 'Fbv4je';

const unwrapGoogleNewsUrl = async (link) => {
  if (!link.includes('news.google.com')) {
    return link;
  }
  gnewsSeen++;
  try {
    const pageRes = await fetch(link, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    const page = await pageRes.text();
    const id = (page.match(/data-n-a-id="([^"]+)"/) || [])[1];
    const ts = (page.match(/data-n-a-ts="([^"]+)"/) || [])[1];
    const sg = (page.match(/data-n-a-sg="([^"]+)"/) || [])[1];
    if (!id || !ts || !sg) {
      return link;
    }

    const inner = JSON.stringify(['garturlreq', [['X', 'X', ['X', 'X'], null, null, 1, 1, 'US:en', null, 1, null, null, null, null, null, 0, 1], 'X', 'X', 1, [1, 1, 1], 1, 1, null, 0, 0, null, 0], id, Number(ts), sg]);
    const payload = JSON.stringify([[[GNEWS_DECODE_RPC, inner, null, 'generic']]]);
    const body = 'f.req=' + encodeURIComponent(payload);

    const decodeRes = await fetch(`https://news.google.com/_/DotsSplashUi/data/batchexecute?rpcids=${GNEWS_DECODE_RPC}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8', 'User-Agent': 'Mozilla/5.0' },
      body,
    });
    const decodeBody = await decodeRes.text();
    const match = decodeBody.match(/garturlres\\?",\\?"(https?:\/\/[^"\\]+)/);
    if (match) {
      gnewsUnwrapped++;
      return match[1];
    }
    return link;
  } catch (e) {
    console.log('⚠️ Could not unwrap Google News URL:', e.message);
    return link;
  }
};

// Create stable unique key from title + date
const createUniqueKey = (title, published) => {
  const normalizedTitle = title.toLowerCase().trim();
  const dateOnly = published.split('T')[0]; // Just YYYY-MM-DD
  return `${normalizedTitle}|||${dateOnly}`;
};

for (const item of items) {
  const json = item.json;

  const title = json.title || '';
  const rawLink = json.link || '';
  const creator = json.creator || json.author || 'Unknown';
  const published = json.pubDate || json.published || json.isoDate || new Date().toISOString();
  const content = json.content || json.contentSnippet || json.description || '';

  // Identify source from the ORIGINAL feed link. identifySource()'s Google News
  // branch keys off the news.google.com domain -- classify before unwrapping, or
  // every Google News item silently stops matching its title-based rules the
  // moment the link resolves to the real (non-google.com) publisher domain.
  const source_feed = identifySource(rawLink, title, creator);

  // Resolve the real destination URL (especially important for Google News,
  // where rawLink is otherwise just an opaque redirect with no reader value)
  const link = await unwrapGoogleNewsUrl(rawLink);

  // Create unique key based on title + date
  const uniqueKey = createUniqueKey(title, published);

  // Check if we've seen this item already
  if (seenItems.has(uniqueKey)) {
    const existing = seenItems.get(uniqueKey);

    // If new source is better (official vs Google News), update it
    const officialSources = ['SEC Press Releases', 'CFTC Regulations', 'Federal Register - Securities', 'FINRA Enforcement News'];
    const existingIsOfficial = officialSources.includes(existing.source_feed);
    const newIsOfficial = officialSources.includes(source_feed);

    if (newIsOfficial && !existingIsOfficial) {
      console.log(`🔄 Upgrading source for "${title.substring(0, 50)}..." from ${existing.source_feed} to ${source_feed}`);
      seenItems.set(uniqueKey, {
        source: creator,
        source_feed: source_feed,
        title: title,
        link: link,
        published: published,
        content: content,
        scraped_at: new Date().toISOString()
      });
    } else {
      console.log(`⚠️ Skipping duplicate: "${title.substring(0, 50)}..." from ${source_feed}`);
    }
    continue;
  }

  // New item - add to map and results
  const itemData = {
    source: creator,
    source_feed: source_feed,
    title: title,
    link: link,
    published: published,
    content: content,
    scraped_at: new Date().toISOString()
  };

  seenItems.set(uniqueKey, itemData);
  results.push({ json: itemData });
}

console.log(`📊 Normalization Summary:
- Total items processed: ${items.length}
- Unique items (by title+date): ${results.length}
- Duplicates removed: ${items.length - results.length}
- Google News links seen: ${gnewsSeen}, unwrapped to real URL: ${gnewsUnwrapped}, fell back to redirect: ${gnewsSeen - gnewsUnwrapped}
`);

return results;

const items = $input.all();

const esc = (v) => String(v == null ? '' : v).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const highPriority = items.filter(i => i.json.urgency_score > 6);
const critical = items.filter(i => i.json.impact_level === 'Critical');
const enforcement = items.filter(i => i.json.is_enforcement);
const crypto = items.filter(i => i.json.keyword_matches?.crypto);
const withDeadlines = items.filter(i => i.json.has_deadline);

// Category distribution
const categoryCount = {};
items.forEach(item => {
  (item.json.categories || []).forEach(cat => {
    categoryCount[cat] = (categoryCount[cat] || 0) + 1;
  });
});
const topCategories = Object.entries(categoryCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

// Source stats
const sourceStats = {};
items.forEach(item => {
  const source = item.json.source_feed;
  if (!sourceStats[source]) {
    sourceStats[source] = { count: 0, avgUrgency: 0 };
  }
  sourceStats[source].count++;
  sourceStats[source].avgUrgency += item.json.urgency_score;
});

Object.keys(sourceStats).forEach(source => {
  sourceStats[source].avgUrgency = (sourceStats[source].avgUrgency / sourceStats[source].count).toFixed(1);
});

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { 
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
      max-width: 1200px; 
      margin: 0 auto; 
      background: #f5f7fa;
      padding: 20px;
    }
    .header { 
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); 
      color: white; 
      padding: 40px; 
      border-radius: 15px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.2);
      margin-bottom: 30px;
    }
    .header h1 { margin: 0 0 10px 0; font-size: 36px; }
    .header p { margin: 0; opacity: 0.9; font-size: 16px; }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 20px;
      margin: 30px 0;
    }
    .stat-card { 
      background: white;
      padding: 25px; 
      border-radius: 12px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      text-align: center;
    }
    .stat-number { 
      font-size: 42px; 
      font-weight: 700; 
      color: #667eea;
      margin: 10px 0;
    }
    .stat-label {
      color: #666;
      font-size: 13px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      font-weight: 600;
    }
    .stat-sublabel {
      color: #999;
      font-size: 11px;
      margin-top: 5px;
    }

    .section {
      background: white;
      padding: 30px;
      margin: 20px 0;
      border-radius: 12px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    }
    .section h2 { 
      margin: 0 0 20px 0; 
      color: #333;
      font-size: 24px;
      border-bottom: 3px solid #667eea;
      padding-bottom: 10px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .section-count {
      background: #667eea;
      color: white;
      padding: 5px 15px;
      border-radius: 20px;
      font-size: 14px;
      font-weight: 600;
    }

    .item { 
      border-left: 4px solid #667eea; 
      padding: 20px; 
      margin: 15px 0; 
      background: #f9f9f9;
      border-radius: 0 8px 8px 0;
    }
    .item:hover {
      transform: translateX(5px);
      transition: transform 0.2s;
    }
    .item.urgent { 
      border-left-color: #dc2626;
      background: #fef2f2;
    }
    .item h3 { 
      margin: 0 0 10px 0; 
      color: #333;
      font-size: 18px;
    }

    .tag {
      display: inline-block;
      padding: 5px 10px;
      border-radius: 6px;
      font-size: 12px;
      margin-right: 8px;
      margin-bottom: 5px;
      font-weight: 500;
    }
    .tag-source { background: #e0e7ff; color: #4338ca; }
    .tag-urgency { background: #fee2e2; color: #991b1b; }
    .tag-impact { background: #fef3c7; color: #92400e; }
    .tag-category { background: #dbeafe; color: #1e40af; }
    .tag-deadline { background: #fecaca; color: #7f1d1d; }

    .badge-critical {
      background: #dc2626;
      color: white;
      padding: 4px 12px;
      border-radius: 6px;
      font-size: 11px;
      font-weight: bold;
      margin-left: 10px;
    }
    .badge-high {
      background: #ea580c;
      color: white;
      padding: 4px 12px;
      border-radius: 6px;
