    }
    .chart-label strong { color: #333; }
    .chart-label span { color: #666; }

    .footer {
      text-align: center;
      color: #888;
      font-size: 12px;
      margin-top: 40px;
      padding: 20px;
    }
  </style>
</head>
<body>
  <div class="header">
    <h1>📊 Mycroft Regulatory Intelligence</h1>
    <p>Daily Digest - ${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
  </div>

  <div class="stats-grid">
    <div class="stat-card">
      <div class="stat-number">${items.length}</div>
      <div class="stat-label">Total Updates</div>
    </div>
    <div class="stat-card">
      <div class="stat-number">${critical.length}</div>
      <div class="stat-label">Critical</div>
      <div class="stat-sublabel">Immediate Action</div>
    </div>
    <div class="stat-card">
      <div class="stat-number">${highPriority.length}</div>
      <div class="stat-label">High Priority</div>
    </div>
    <div class="stat-card">
      <div class="stat-number">${enforcement.length}</div>
      <div class="stat-label">Enforcement</div>
    </div>
    <div class="stat-card">
      <div class="stat-number">${crypto.length}</div>
      <div class="stat-label">Crypto Related</div>
    </div>
    <div class="stat-card">
      <div class="stat-number">${withDeadlines.length}</div>
      <div class="stat-label">Deadlines</div>
    </div>
  </div>

  <div class="section">
    <h2>📈 Source Distribution</h2>
    ${Object.entries(sourceStats).sort((a, b) => b[1].count - a[1].count).map(([source, stats]) => {
      const percentage = (stats.count / items.length * 100).toFixed(1);
      return `
        <div>
          <div class="chart-label">
            <strong>${source}</strong>
            <span>${stats.count} items · Avg Urgency: ${stats.avgUrgency}/10</span>
          </div>
          <div class="chart-bar">
            <div class="chart-fill" style="width: ${percentage}%">
              ${percentage}%
            </div>
          </div>
        </div>
      `;
    }).join('')}
  </div>

  ${topCategories.length > 0 ? `
  <div class="section">
    <h2>🏷️ Top Categories</h2>
    ${topCategories.map(([category, count]) => {
      const percentage = (count / items.length * 100).toFixed(1);
      return `
        <div>
          <div class="chart-label">
            <strong>${category.charAt(0).toUpperCase() + category.slice(1)}</strong>
            <span>${count} items</span>
          </div>
          <div class="chart-bar">
            <div class="chart-fill" style="width: ${percentage}%">
              ${percentage}%
            </div>
          </div>
        </div>
      `;
    }).join('')}
  </div>
  ` : ''}

  ${highPriority.length > 0 ? `
  <div class="section">
    <h2>
      🔥 High Priority Items
      <span class="section-count">${highPriority.length}</span>
    </h2>
    ${highPriority.slice(0, 10).map(item => `
      <div class="item ${item.json.urgency_score >= 9 ? 'urgent' : ''}">
        <h3>
          ${esc(item.json.title)}
          ${item.json.impact_level === 'Critical' ? '<span class="badge-critical">CRITICAL</span>' : ''}
          ${item.json.impact_level === 'High' ? '<span class="badge-high">HIGH</span>' : ''}
        </h3>
        <div>
          <span class="tag tag-source">📍 ${esc(item.json.source_feed)}</span>
          <span class="tag tag-urgency">⚡ ${item.json.urgency_score}/10</span>
          <span class="tag tag-impact">📊 ${item.json.impact_level}</span>
          ${item.json.has_deadline ? '<span class="tag tag-deadline">⏰ Deadline</span>' : ''}
          ${(item.json.categories || []).slice(0, 2).map(cat => 
            `<span class="tag tag-category">🏷️ ${esc(cat)}</span>`
          ).join('')}
        </div>
        <p style="color: #666; margin: 12px 0; line-height: 1.5;">${esc(item.json.content.substring(0, 200))}...</p>
        <a href="${esc(item.json.link)}" target="_blank">Read Full Document →</a>
      </div>
    `).join('')}
  </div>
  ` : ''}

  ${enforcement.length > 0 ? `
  <div class="section">
    <h2>
      ⚖️ Enforcement Actions
      <span class="section-count">${enforcement.length}</span>
    </h2>
    ${enforcement.slice(0, 8).map(item => `
      <div class="item">
        <h3>${esc(item.json.title)}</h3>
        <div>
          <span class="tag tag-source">📍 ${esc(item.json.source_feed)}</span>
          <span class="tag tag-urgency">📅 ${new Date(item.json.published).toLocaleDateString()}</span>
        </div>
        <a href="${esc(item.json.link)}" target="_blank">Read More →</a>
      </div>
    `).join('')}
  </div>
  ` : ''}

  ${crypto.length > 0 ? `
  <div class="section">
    <h2>
      ₿ Cryptocurrency & Digital Assets
      <span class="section-count">${crypto.length}</span>
    </h2>
    ${crypto.slice(0, 5).map(item => `
      <div class="item">
        <h3>${esc(item.json.title)}</h3>
        <div>
          <span class="tag tag-source">📍 ${esc(item.json.source_feed)}</span>
          <span class="tag tag-urgency">⚡ ${item.json.urgency_score}/10</span>
        </div>
        <a href="${esc(item.json.link)}" target="_blank">Read More →</a>
      </div>
    `).join('')}
  </div>
  ` : ''}

  ${withDeadlines.length > 0 ? `
  <div class="section">
    <h2>
      ⏰ Compliance Deadlines
      <span class="section-count">${withDeadlines.length}</span>
    </h2>
    ${withDeadlines.slice(0, 5).map(item => `
      <div class="item" style="border-left-color: #f59e0b;">
        <h3>${esc(item.json.title)}</h3>
        <div>
          <span class="tag tag-source">📍 ${esc(item.json.source_feed)}</span>
          <span class="tag tag-deadline">⏰ Contains Deadline</span>
        </div>
        <a href="${esc(item.json.link)}" target="_blank">View Details →</a>
      </div>
    `).join('')}
  </div>
  ` : ''}

  <div class="footer">
    <p>Generated by Mycroft Regulatory Intelligence System</p>
    <p>Powered by n8n | ${new Date().toISOString()}</p>
  </div>
</body>
</html>`;

const buffer = Buffer.from(html, 'utf-8');
const filename = `mycroft-report-${new Date().toISOString().split('T')[0]}.html`;

return [{
  json: {
    report_date: new Date().toISOString(),
    total_items: items.length,
    high_priority: highPriority.length,
    critical: critical.length,
    filename: filename
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: filename,
      fileExtension: 'html'
    }
  }
}];

const items = $input.all();
const results = [];

// Financial regulatory keywords to track
const keywordCategories = {
  enforcement: ['enforcement', 'penalty', 'fine', 'violation', 'sanctioned', 'charged', 'settled'],
  compliance: ['compliance', 'audit', 'examination', 'reporting', 'disclosure', 'filing'],
  crypto: ['cryptocurrency', 'crypto', 'bitcoin', 'blockchain', 'digital asset', 'token'],
  securities: ['securities', 'investment advisor', 'investment adviser', 'broker-dealer', 'mutual fund', 'etf'],
  derivatives: ['derivatives', 'futures', 'options', 'swap', 'cftc', 'commodity'],
  fraud: ['fraud', 'misrepresentation', 'ponzi', 'manipulation', 'insider trading', 'scheme']
};

function extractKeywords(text) {
  const lowerText = text.toLowerCase();
  const matched = {};

  for (const [category, keywords] of Object.entries(keywordCategories)) {
    matched[category] = keywords.some(kw => lowerText.includes(kw));
  }

  return matched;
}

function calculateBasicUrgency(title, content) {
  const text = (title + ' ' + content).toLowerCase();
  let score = 5; // baseline

  // Urgency indicators
  if (text.includes('immediate') || text.includes('emergency')) score += 3;
  if (text.includes('deadline') || text.includes('must comply') || text.includes('effective date')) score += 2;
  if (text.includes('enforcement') || text.includes('penalty') || text.includes('fine')) score += 2;
  if (text.includes('new rule') || text.includes('proposed rule') || text.includes('final rule')) score += 1;
  if (text.includes('fraud') || text.includes('manipulation')) score += 1;
  if (text.includes('cease and desist') || text.includes('suspension')) score += 1;

  return Math.min(score, 10);
}

function determineImpactLevel(urgencyScore, isEnforcement, isFraud) {
  if (urgencyScore >= 9 || isFraud) return 'Critical';
  if (urgencyScore >= 7 || isEnforcement) return 'High';
  if (urgencyScore >= 5) return 'Medium';
  return 'Low';
}

for (const item of items) {
  const json = item.json;
  const fullText = `${json.title} ${json.content}`;
  const keywordMatches = extractKeywords(fullText);
  const urgencyScore = calculateBasicUrgency(json.title, json.content);

  results.push({
    json: {
      ...json,
      keyword_matches: keywordMatches,
      urgency_score: urgencyScore,
      impact_level: determineImpactLevel(urgencyScore, keywordMatches.enforcement, keywordMatches.fraud),
      word_count: json.content.split(' ').length,
      has_deadline: fullText.toLowerCase().includes('deadline'),
      is_enforcement: keywordMatches.enforcement,
      categories: Object.entries(keywordMatches).filter(([k, v]) => v).map(([k]) => k)
    }
  });
}

return results;

parameters.query:
INSERT INTO regulatory_feeds (
  source_feed, source, title, link, published, content,
  urgency_score, impact_level, keyword_matches, categories,
  word_count, has_deadline, is_enforcement, scraped_at
) VALUES (
  $1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb, $10::jsonb, $11, $12, $13, $14
)
ON CONFLICT (title, DATE(published)) DO NOTHING
