const insertResults = $input.all();

// Rows actually inserted return via RETURNING * with a numeric id (and title).
// Conflicted rows return nothing; n8n may emit an empty placeholder item — exclude those.
const newItems = insertResults.filter(i => i.json && Number.isInteger(i.json.id) && i.json.title);

console.log(`📊 Insert summary: ${insertResults.length} processed, ${newItems.length} new, ${insertResults.length - newItems.length} duplicate/empty`);

if (newItems.length === 0) {
  console.log('✅ No new items - all were duplicates!');
  return [];
}

return newItems;

const items = $input.all();

const OLLAMA_URL = 'http://localhost:11434/api/generate';
const OLLAMA_MODEL = 'llama3.2:3b'; // matches Regulatory_QA's existing convention (backend/app/config.py)

const PROMPT_TEMPLATE = (title, content, impactLevel, urgencyScore, triggers) => `You are reviewing a financial regulatory alert that a keyword-based scorer flagged as high priority. Your job: decide if this is a GENUINE urgent financial-regulatory event, or NOISE that only got flagged because of an incidental keyword match.

Title: ${title}
Content excerpt: ${content}
Keyword-scorer's reasoning: this item was scored "${impactLevel}" (urgency ${urgencyScore}/10) because the text contains the trigger word(s): ${triggers}

Impact level guide:
- Critical: an actual enforcement action, fraud charge, or a rule change that takes effect immediately with real compliance consequences.
- High: a substantive new rule or proposal that firms need to act on, but not urgent/enforcement.
- Medium: routine agency business - standard rulemaking notices, procedural filings, administrative housekeeping.
- Low: minor administrative notices with no compliance impact.

Answer with ONLY a JSON object, no other text, in this exact format:
{"verdict": "confirm" or "downgrade", "corrected_impact_level": "Critical" or "High" or "Medium" or "Low", "reasoning": "one sentence"}
`;

// Named false-positive trigger detection — same words the keyword scorer itself
// checks for (calculateBasicUrgency in Keyword Analysis & Urgency Scoring), so
// we can tell the LLM specifically which word(s) drove the score.
function detectTriggers(title, content) {
  const text = `${title} ${content}`.toLowerCase();
  const found = [];
  if (text.includes('immediate') || text.includes('emergency')) found.push("'immediate'/'emergency'");
  if (text.includes('deadline') || text.includes('must comply') || text.includes('effective date')) found.push("'deadline'/'must comply'/'effective date'");
  if (text.includes('enforcement') || text.includes('penalty') || text.includes('fine')) found.push("'enforcement'/'penalty'/'fine'");
  if (text.includes('fraud') || text.includes('manipulation')) found.push("'fraud'/'manipulation'");
  return found.length ? found.join(', ') : '(no specific trigger word identified)';
}

async function callOllama(prompt) {
  const response = await fetch(OLLAMA_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: OLLAMA_MODEL,
      prompt,
      stream: false,
      options: { temperature: 0.1, num_predict: 200 },
    }),
  });
  if (!response.ok) {
    throw new Error(`Ollama returned ${response.status}`);
  }
  const result = await response.json();
  return JSON.parse(result.response.trim());
}

const results = [];
let llmSeen = 0;
let llmDowngraded = 0;
let llmErrors = 0;

// Sequential, not parallelized (same deliberate choice as the B3 Google News
// unwrap: one local model instance, no benefit to bursty parallel calls, and
// it keeps load on the machine predictable for a scheduled batch job).
for (const item of items) {
  const json = item.json;

  // Only spend an LLM call on items that would actually trigger the alert
  // path (High Priority Filter gates on urgency_score > 6) — no need to
  // review items that were never going to alert in the first place.
  if (json.urgency_score > 6) {
    llmSeen++;
    try {
      const triggers = detectTriggers(json.title, json.content || '');
      const prompt = PROMPT_TEMPLATE(
        json.title,
        (json.content || '').slice(0, 600),
        json.impact_level,
        json.urgency_score,
        triggers
      );
      const verdict = await callOllama(prompt);
      const isDowngrade = verdict.verdict === 'downgrade';
      if (isDowngrade) llmDowngraded++;
      results.push({
        json: {
          ...json,
          llm_reviewed: true,
          llm_verdict: verdict.verdict,
          llm_corrected_impact_level: verdict.corrected_impact_level,
          llm_reasoning: verdict.reasoning,
          llm_downgrade: isDowngrade,
        },
      });
      continue;
    } catch (e) {
      // Fail open: on any Ollama/network/parse error, the item behaves
      // exactly as it would have before this step existed — a broken
      // re-score never blocks or breaks the run (same principle as B3's
      // unwrap fallback).
      llmErrors++;
      results.push({
        json: {
          ...json,
          llm_reviewed: false,
          llm_downgrade: false,
          llm_error: String(e.message || e),
        },
      });
      continue;
    }
  }

  // Below the alert threshold — no LLM call needed, not reviewed.
  results.push({
    json: {
      ...json,
      llm_reviewed: false,
      llm_downgrade: false,
    },
  });
}

console.log(`Layer 2 LLM re-score: ${llmSeen} items reviewed, ${llmDowngraded} downgraded, ${llmErrors} errors (fail-open, treated as not downgraded)`);

return results;
